import * as React from 'react'
import { ChevronDown } from 'lucide-react'
import { cn } from '@/lib/utils'
import { Tabs, TabsList, TabsTrigger, TabsContent } from '@/components/ui/tabs'
import { Checkbox } from '@/components/ui/checkbox'
import { Spin } from '@/components/ui/spin'
export function CardPlus({
  title,
  description,
  extra,
  collapsible,
  defaultCollapsed,
  children,
  className,
  footer,
  tabs,
  checked,
  onCheckedChange,
  loading,
}: {
  title: React.ReactNode
  description?: string
  extra?: React.ReactNode
  collapsible?: boolean
  defaultCollapsed?: boolean
  children: React.ReactNode
  className?: string
  footer?: React.ReactNode
  tabs?: { key: string; label: string; children: React.ReactNode }[]
  checked?: boolean
  onCheckedChange?: (checked: boolean) => void
  loading?: boolean
}) {
  const [collapsed, setCollapsed] = React.useState(!!defaultCollapsed)
  return (
    <section
      className={cn('overflow-hidden rounded-xl border bg-card text-card-foreground', className)}
    >
      <header className="flex items-center justify-between gap-3 border-b p-5">
        {onCheckedChange && (
          <Checkbox
            checked={checked}
            onCheckedChange={(value) => onCheckedChange(!!value)}
            aria-label="Select card"
          />
        )}
        <div>
          <h3 className="text-sm font-semibold">{title}</h3>
          {description && <p className="mt-1 text-xs text-muted-foreground">{description}</p>}
        </div>
        <div className="flex items-center gap-2">
          {extra}
          {collapsible && (
            <button
              type="button"
              aria-label={collapsed ? 'Expand card' : 'Collapse card'}
              aria-expanded={!collapsed}
              onClick={() => setCollapsed((v) => !v)}
            >
              <ChevronDown size={16} className={cn('transition', collapsed && '-rotate-90')} />
            </button>
          )}
        </div>
      </header>
      {!collapsed && (
        <>
          <Spin spinning={!!loading}>
            <div className="p-5">
              {tabs?.length ? (
                <Tabs defaultValue={tabs[0].key}>
                  <TabsList>
                    {tabs.map((tab) => (
                      <TabsTrigger key={tab.key} value={tab.key}>
                        {tab.label}
                      </TabsTrigger>
                    ))}
                  </TabsList>
                  {tabs.map((tab) => (
                    <TabsContent key={tab.key} value={tab.key}>
                      {tab.children}
                    </TabsContent>
                  ))}
                </Tabs>
              ) : (
                children
              )}
            </div>
          </Spin>
          {footer && (
            <footer className="border-t bg-muted/20 px-5 py-3 text-xs text-muted-foreground">
              {footer}
            </footer>
          )}
        </>
      )}
    </section>
  )
}

import { clsx, type ClassValue } from 'clsx'
import { twMerge } from 'tailwind-merge'
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}

import * as React from 'react'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from '@/lib/utils'
import { Tabs as TabsPrimitive } from 'radix-ui'

function Tabs({
  className,
  orientation = 'horizontal',
  ...props
}: React.ComponentProps<typeof TabsPrimitive.Root>) {
  return (
    <TabsPrimitive.Root
      data-slot="tabs"
      data-orientation={orientation}
      orientation={orientation}
      className={cn('group/tabs flex gap-2 data-[orientation=horizontal]:flex-col', className)}
      {...props}
    />
  )
}

const tabsListVariants = cva(
  'group/tabs-list inline-flex w-fit items-center justify-center rounded-lg p-[3px] text-muted-foreground group-data-[orientation=horizontal]/tabs:h-9 group-data-[orientation=vertical]/tabs:h-fit group-data-[orientation=vertical]/tabs:flex-col data-[variant=line]:rounded-none',
  {
    variants: {
      variant: {
        default: 'bg-muted',
        line: 'gap-1 bg-transparent',
      },
    },
    defaultVariants: {
      variant: 'default',
    },
  },
)

function TabsList({
  className,
  variant = 'default',
  ...props
}: React.ComponentProps<typeof TabsPrimitive.List> & VariantProps<typeof tabsListVariants>) {
  return (
    <TabsPrimitive.List
      data-slot="tabs-list"
      data-variant={variant}
      className={cn(tabsListVariants({ variant }), className)}
      {...props}
    />
  )
}

function TabsTrigger({ className, ...props }: React.ComponentProps<typeof TabsPrimitive.Trigger>) {
  return (
    <TabsPrimitive.Trigger
      data-slot="tabs-trigger"
      className={cn(
        "relative inline-flex h-[calc(100%-1px)] flex-1 items-center justify-center gap-1.5 rounded-md border border-transparent px-2 py-1 text-sm font-medium whitespace-nowrap text-muted-foreground transition-all group-data-[orientation=vertical]/tabs:w-full group-data-[orientation=vertical]/tabs:justify-start hover:text-foreground focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50 focus-visible:outline-1 focus-visible:outline-ring disabled:pointer-events-none disabled:opacity-50 group-data-[variant=default]/tabs-list:data-[state=active]:shadow-sm group-data-[variant=line]/tabs-list:data-[state=active]:shadow-none dark:text-muted-foreground dark:hover:text-foreground [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4",
        'group-data-[variant=line]/tabs-list:bg-transparent group-data-[variant=line]/tabs-list:data-[state=active]:bg-transparent dark:group-data-[variant=line]/tabs-list:data-[state=active]:border-transparent dark:group-data-[variant=line]/tabs-list:data-[state=active]:bg-transparent',
        'data-[state=active]:bg-background data-[state=active]:text-foreground dark:data-[state=active]:border-input dark:data-[state=active]:bg-input/30 dark:data-[state=active]:text-foreground',
        'after:absolute after:bg-foreground after:opacity-0 after:transition-opacity group-data-[orientation=horizontal]/tabs:after:inset-x-0 group-data-[orientation=horizontal]/tabs:after:bottom-[-5px] group-data-[orientation=horizontal]/tabs:after:h-0.5 group-data-[orientation=vertical]/tabs:after:inset-y-0 group-data-[orientation=vertical]/tabs:after:-right-1 group-data-[orientation=vertical]/tabs:after:w-0.5 group-data-[variant=line]/tabs-list:data-[state=active]:after:opacity-100',
        className,
      )}
      {...props}
    />
  )
}

function TabsContent({ className, ...props }: React.ComponentProps<typeof TabsPrimitive.Content>) {
  return (
    <TabsPrimitive.Content
      data-slot="tabs-content"
      className={cn('flex-1 outline-none', className)}
      {...props}
    />
  )
}

export { Tabs, TabsList, TabsTrigger, TabsContent, tabsListVariants }
export interface TabItem {
  value: string
  label: React.ReactNode
  content: React.ReactNode
  disabled?: boolean
  closable?: boolean
}
export function WorkspaceTabs({
  items,
  value,
  onValueChange,
  onItemsChange,
  reorderable = true,
  orientation = 'horizontal',
}: {
  items: TabItem[]
  value: string
  onValueChange: (value: string) => void
  onItemsChange?: (items: TabItem[]) => void
  reorderable?: boolean
  orientation?: 'horizontal' | 'vertical'
}) {
  return (
    <Tabs orientation={orientation} value={value} onValueChange={onValueChange}>
      <div className="max-w-full overflow-x-auto">
        <div className="flex flex-wrap items-center gap-1">
          <TabsList className="h-auto min-w-max bg-muted p-1">
            {items.map((item, index) => (
              <div
                key={item.value}
                className="flex items-center"
                draggable={!!onItemsChange && reorderable}
                onDragStart={(event) => event.dataTransfer.setData('text/plain', item.value)}
                onDragOver={(event) => event.preventDefault()}
                onDrop={(event) => {
                  event.preventDefault()
                  const from = items.findIndex(
                    (i) => i.value === event.dataTransfer.getData('text/plain'),
                  )
                  if (from < 0 || from === index) return
                  const next = [...items],
                    moved = next.splice(from, 1)[0]
                  next.splice(index, 0, moved)
                  onItemsChange?.(next)
                }}
              >
                <TabsTrigger value={item.value} disabled={item.disabled}>
                  {item.label}
                </TabsTrigger>
              </div>
            ))}
          </TabsList>
          {items
            .filter((item) => item.closable)
            .map(
              (item, index) =>
                onItemsChange && (
                  <button
                    key={item.value}
                    type="button"
                    className="px-1 text-xs text-muted-foreground"
                    aria-label={`Close ${typeof item.label === 'string' ? item.label : 'tab'}`}
                    onClick={() => {
                      const next = items.filter((i) => i.value !== item.value)
                      onItemsChange(next)
                      if (value === item.value)
                        onValueChange(
                          next[Math.max(0, items.findIndex((tab) => tab.value === item.value) - 1)]
                            ?.value ?? '',
                        )
                    }}
                  >
                    × <span className="sr-only">{item.label}</span>
                  </button>
                ),
            )}
        </div>
      </div>
      {items.map((item) => (
        <TabsContent key={item.value} value={item.value}>
          {item.content}
        </TabsContent>
      ))}
    </Tabs>
  )
}

import * as React from 'react'
import { cn } from '@/lib/utils'
import { CheckIcon } from 'lucide-react'
import { Checkbox as CheckboxPrimitive } from 'radix-ui'

function Checkbox({ className, ...props }: React.ComponentProps<typeof CheckboxPrimitive.Root>) {
  return (
    <CheckboxPrimitive.Root
      data-slot="checkbox"
      className={cn(
        'peer size-4 shrink-0 rounded-[4px] border border-input shadow-xs transition-shadow outline-none focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50 disabled:cursor-not-allowed disabled:opacity-50 aria-invalid:border-destructive aria-invalid:ring-destructive/20 data-[state=checked]:border-primary data-[state=checked]:bg-primary data-[state=checked]:text-primary-foreground dark:bg-input/30 dark:aria-invalid:ring-destructive/40 dark:data-[state=checked]:bg-primary',
        className,
      )}
      {...props}
    >
      <CheckboxPrimitive.Indicator
        data-slot="checkbox-indicator"
        className="grid place-content-center text-current transition-none"
      >
        <CheckIcon className="size-3.5" />
      </CheckboxPrimitive.Indicator>
    </CheckboxPrimitive.Root>
  )
}

export { Checkbox }
export function CheckboxGroup({
  options,
  value = [],
  onValueChange,
  disabled,
}: {
  options: { value: string; label: React.ReactNode; disabled?: boolean }[]
  value?: string[]
  onValueChange?: (value: string[]) => void
  disabled?: boolean
}) {
  return (
    <div role="group" className="flex flex-wrap gap-4">
      {options.map((option) => (
        <label key={option.value} className="flex items-center gap-2 text-sm">
          <Checkbox
            checked={value.includes(option.value)}
            disabled={disabled || option.disabled}
            onCheckedChange={(checked) =>
              onValueChange?.(
                checked ? [...value, option.value] : value.filter((v) => v !== option.value),
              )
            }
          />
          {option.label}
        </label>
      ))}
    </div>
  )
}

import * as React from 'react'
import { Loader2 } from 'lucide-react'
import { cn } from '@/lib/utils'
export function Spin({
  spinning = true,
  children,
  label = 'Loading',
  className,
  delay = 0,
  minimumDuration = 0,
}: {
  spinning?: boolean
  children?: React.ReactNode
  label?: string
  className?: string
  delay?: number
  minimumDuration?: number
}) {
  const [visible, setVisible] = React.useState(spinning && delay === 0),
    shown = React.useRef(visible ? Date.now() : 0)
  React.useEffect(() => {
    const duration = spinning ? delay : Math.max(0, minimumDuration - (Date.now() - shown.current)),
      timer = setTimeout(() => {
        setVisible(spinning)
        if (spinning) shown.current = Date.now()
      }, duration)
    return () => clearTimeout(timer)
  }, [spinning, delay, minimumDuration])
  const indicator = (
    <span role="status" className="inline-flex items-center gap-2 text-sm text-muted-foreground">
      <Loader2 className="size-5 animate-spin" />
      {label}
    </span>
  )
  return children ? (
    <div className={cn('relative', className)} aria-busy={spinning}>
      {children}
      {visible && (
        <div className="absolute inset-0 flex items-center justify-center rounded-lg bg-background/75 backdrop-blur-[1px]">
          {indicator}
        </div>
      )}
    </div>
  ) : visible ? (
    <span className={className}>{indicator}</span>
  ) : null
}
